import{a as B}from"./chunks/chunk-VBQ3WWG4.js";import{a as Te}from"./chunks/chunk-WJYCEXWY.js";import{a as Ae}from"./chunks/chunk-BNRI64JV.js";import{a as Ce}from"./chunks/chunk-JI577UDS.js";import"./chunks/chunk-VAMAXJF7.js";import{a as ze}from"./chunks/chunk-S7QFZVUB.js";var Se={id:"foundations",title:"Visualization foundations",subtitle:"Use a synthetic city transit dataset to compare routes, read trends, and investigate relationships and unusual values.",reference:"CPS 5745 Day 01, Visualization introduction. CPS 5745 Day 02, Visualization and analysis in software.",lessons:[{id:"visual-encoding",title:"Visual encoding and comparison",subtitle:"Turn one number per route into a fair comparison.",kind:"bars",slides:[{title:"Choose a mark and a channel",body:"A mark is a visible object such as a bar or dot. An encoding connects a data field to a feature such as position, length, or color. For comparing numerical values, aligned bars let you compare lengths from a common baseline.",example:"Each bar represents one route. Its length represents weekly rides, and its label identifies the route."},{title:"Read the scale before the marks",body:"A zero baseline keeps bar lengths proportional to the values. Labels and units let you check the exact difference after spotting the pattern.",example:"Find the two longest bars, then check their ride counts before deciding how far apart they are."},{title:"Match the quantity to the question",body:"A total answers a question about volume. A rate divides the total by a relevant quantity and answers a different question. Use the same reporting period and units across routes.",example:"Weekly rides answer which route carried the most passengers. Rides per trip would answer which route carried more passengers per scheduled trip."}],quiz:[{prompt:"Which visual feature should represent weekly rides in a bar chart?",options:["Length from a shared baseline","Alphabetical order of route names","The hue assigned to each route"],correct:0,explanation:"Length encodes the ride count on one scale. The route label or color can identify the category."},{prompt:"Which setup makes the ratio between two bar lengths meaningful?",options:["A vertical scale chosen independently for each route","One scale starting at zero","A different bar width for every route"],correct:1,explanation:"When the bars share one zero baseline, the ratio of two bar lengths is the ratio of the values."},{prompt:"The planning team asks which route carried more passengers per scheduled trip. Which measure answers that question?",options:["Weekly rides","Total scheduled trips","Weekly rides divided by weekly scheduled trips"],correct:2,explanation:"Dividing the ride count by the number of trips gives rides per trip. Use counts from the same week."}]},{id:"time-series",title:"Trends and time series",subtitle:"Follow weekly ridership in the order it happened.",kind:"line",slides:[{title:"Let time set the horizontal position",body:"A time series is a sequence of measurements indexed by time. Points show the observations. Connecting them in time order helps you see change from one observation to the next.",example:"Trace the line from its earliest week to its latest, and find where weekly rides rose or fell."},{title:"Separate change from variability",body:"A trend is a sustained direction over the period you inspect. Individual weeks can rise or fall around that direction. Compare several intervals before describing the whole series.",example:"Find one week where the line dips. Check the weeks on both sides to decide whether the dip is brief."},{title:"Keep the observation context visible",body:"Check the date range, interval, and units before comparing series. Use a visible gap for an unobserved week and label the reason if you know it. Use zero only for a week observed to have zero rides.",example:"If a weekly ridership report is missing, the chart should show where the missing measurement belongs."}],quiz:[{prompt:"In what order should a weekly ridership line connect its observations?",options:["Largest ride count first","Alphabetical order by route name","Earliest week to latest week"],correct:2,explanation:"Chronological order preserves the sequence. You can then see what changed between successive weeks."},{prompt:"A line falls one week and then rises again. What should you inspect before concluding ridership is declining?",options:["The direction across the full time window","The color of the line","The total number of route names"],correct:0,explanation:"A single week captures one change. The surrounding observations provide evidence about the longer direction."},{prompt:"A weekly report was never recorded. How should its place in the series appear?",options:["As a measured zero","As a gap marked missing","As an exact copy of the last value"],correct:1,explanation:"A gap preserves the missing week without inventing a count. Zero is reserved for an observed count of zero."}]},{id:"correlation",title:"Scatterplots and correlation",subtitle:"Explore how service frequency and ridership vary together.",kind:"scatter",slides:[{title:"Read the cloud of points",body:"A scatterplot gives each observation two positions from two numeric fields. Inspect direction, shape, spread, and isolated points before summarizing the relationship.",example:"Each dot represents a district with a service frequency and a ridership count. Use the axis labels to read which field is measured on each axis."},{title:"Summarize the linear pattern",body:"Pearson correlation r ranges from -1 to 1 and summarizes the direction and strength of linear association. Values close to zero can still occur along a curved relationship. A fitted line helps you see which observations sit above or below its prediction.",example:"Compare the overall tilt with the spread around it. Inspect any isolated district before drawing conclusions from a fitted line or correlation."},{title:"Turn the view to inspect a third field",body:"A 3D scatterplot uses depth to encode a third numeric field. Rotation changes the viewpoint and can reveal overlapping marks. Each observation keeps the same values while the camera moves.",example:"Use travel time as depth. Return to 2D for a direct comparison of service frequency and ridership."}],quiz:[{prompt:"The points tend to rise from left to right. What does that pattern support?",options:["The measured fields tend to increase together","All districts have the same ridership","Increasing frequency guarantees increased ridership"],correct:0,explanation:"An upward pattern shows positive association in the observed fields. A causal claim needs a separate study design."},{prompt:"What might a clear U-shaped cloud show even when Pearson r is close to zero?",options:["The axes represent the same measurement","A strong positive linear pattern","A nonlinear relationship"],correct:2,explanation:"Pearson r summarizes a straight-line pattern. The opposing directions on either side of a U can cancel in that summary."},{prompt:"What changes when you rotate the 3D scatterplot?",options:["The measured travel times","Your viewpoint and which marks overlap","The district assigned to each observation"],correct:1,explanation:"Rotation changes the projection onto the screen. The service frequency, ridership, and travel time of each district stay fixed."}]},{id:"distributions",title:"Distributions and outliers",subtitle:"Read the spread of delays and investigate unusual observations.",kind:"histogram",slides:[{title:"Group observations into bins",body:"A histogram groups numerical values into adjacent intervals, or bins. In an equal-width count histogram, bar height shows the number of observations in each interval. Bin width can reveal or hide details of the same data.",example:"Compare the intervals with many delays to the sparse right tail. Check each interval boundary before interpreting its count."},{title:"Describe spread with quartiles",body:"The five-number summary gives the minimum, lower quartile Q1, median, upper quartile Q3, and maximum. The interquartile range, Q3 minus Q1, measures the width of the middle half. In a Tukey boxplot, the whiskers reach the most extreme observed values within the fences.",example:"Use Q1 and Q3 to describe the spread of typical delays, then compare it with the full range."},{title:"Use fences to flag observations",body:"Calculate the lower fence as Q1 minus 1.5 times the IQR and the upper fence as Q3 plus 1.5 times the IQR. Values strictly outside either fence are flagged for inspection. Check the record and its context before deciding how to handle it.",example:"Inspect the unusually long delay. Its original record can help you distinguish a service interruption from a data entry error."}],quiz:[{prompt:"What does the height of a bar in an equal-width delay count histogram represent?",options:["The largest delay in the interval","The number of delays in the interval","The route with the longest delay"],correct:1,explanation:"Each observation belongs to one interval. The bar height is the count assigned to that interval."},{prompt:"Which quantity measures the width of the middle half of the delays?",options:["Q3 minus Q1","Maximum minus minimum","Median minus minimum"],correct:0,explanation:"Q1 and Q3 bracket the middle half. Their difference is the interquartile range."},{prompt:"A delay lies above the upper IQR fence. What is the next useful step?",options:["Replace it with the median","Delete it before checking","Inspect the record and its context"],correct:2,explanation:"The fence identifies an unusual observation. Its source and circumstances help you decide how to handle it."}]}]};var Ie=[{id:"unit-2",title:"SQL for visualization",subtitle:"Turn rows into reliable summaries before drawing a chart.",reference:"CPS 5745 Day 03, Databases and SQL. CPS 5745 Day 04, SQL aggregations.",lessons:[{id:"sql-group-by",title:"Filter and aggregate rows",subtitle:"Build one comparable chart value for each route.",kind:"bars",slides:[{title:"Know what each row represents",body:"A table can have several records for one route. GROUP BY collects rows with the same key so an aggregate can produce one summary per group. The chosen key determines what one bar represents.",example:"Grouping by route gives one bar per route. Grouping by route and week gives one summary per route in each week."},{title:"Choose a measure with units",body:"SUM adds the measured values, AVG computes the mean of the measured values, and COUNT(*) counts rows. SUM and AVG skip NULL entries. A mean describes the values recorded for the group, so inspect how many observations contributed.",example:"For three records with 20 rides, 40 rides, and a missing count, SUM is 60 rides, AVG is 30 rides per recorded row, and COUNT(*) is 3."},{title:"Filter at the right stage",body:"WHERE limits the input rows before GROUP BY. HAVING keeps or removes a group after its aggregate has been computed. Apply a common reporting period to each group you compare.",example:"Use WHERE to select the reporting week and HAVING SUM(rides) >= 100 to keep groups with at least 100 rides in that week."}],quiz:[{prompt:"You need one bar per route and week. Which grouping gives that level of detail?",options:["GROUP BY route","GROUP BY route, week","GROUP BY rides"],correct:1,explanation:"The route and week together identify each group. Each bar summarizes its own set of records."},{prompt:"Ride observations are 20, 40, and NULL. What is AVG(rides)?",options:["20","60","30"],correct:2,explanation:"AVG divides the total of the two recorded values, 60, by the number of recorded values, 2."},{prompt:"Which clause keeps only routes whose computed total is at least 100?",options:["HAVING SUM(rides) >= 100","WHERE rides >= 100","ORDER BY rides DESC"],correct:0,explanation:"HAVING evaluates the total at the group level. WHERE rides >= 100 would evaluate each input row separately."}]},{id:"sql-time-buckets",title:"Summarize data across time",subtitle:"Choose a reporting interval and show the dates in order.",kind:"line",slides:[{title:"Define reporting intervals",body:"A time bucket groups timestamps into a reporting interval such as a day, week, or month. Decide where the intervals begin, which time zone applies, and which measure each point reports.",example:"Use one consistent definition of a reporting week for all routes. Weekly sums and weekly averages describe different quantities."},{title:"Sort buckets by their dates",body:"Group records using a calendar key such as the start date of the interval. Order the query result by that key before drawing the line. A display label can be formatted separately.",example:"Use the date 2026-02-01 as a February bucket key. You can display it as Feb 2026 while preserving its position in the yearly sequence."},{title:"Check what a missing bucket means",body:"A bucket with no input records may be absent from the query result. Compare the result with the expected calendar to expose unobserved intervals. When a record establishes a count of zero, the chart can show zero.",example:"Use a gap when the April report is missing. Compare several complete intervals before interpreting a change in totals."}],quiz:[{prompt:"A chart connects monthly totals in alphabetical order by month name. What should change?",options:["Sort by the date of each month start","Sort by the largest total","Use a brighter palette"],correct:0,explanation:"A date key orders the intervals chronologically, including intervals from different years."},{prompt:"The June reporting file never arrived. What should the chart show at June?",options:["Zero rides","A gap marked missing","A repeat of May\u2019s total"],correct:1,explanation:"A missing report supplies no ride count. Mark the absent interval so viewers can distinguish it from an observed zero."},{prompt:"Why can a monthly ride total be higher in a longer month even when rides per day are stable?",options:["Sorting changes the total","A longer month always has a higher average","The total adds more days of rides"],correct:2,explanation:"A total depends on the number of days as well as the typical daily count. A daily rate answers a separate comparison question."}]}]},{id:"unit-3",title:"Interactive web charts",subtitle:"Connect chart controls, visual marks, and the data they display.",reference:"CPS 5745 Day 10, Interactive and dynamic visualization. Day 12, JavaScript events. Days 13\u201317, Web graphics and chart integration.",lessons:[{id:"web-encoding",title:"From events to chart state",subtitle:"Trace how an interaction changes the chart.",kind:"bars",slides:[{title:"Separate values, state, and rendering",body:"The data store contains the measurements. Chart state describes choices such as sort order, filters, and selection. The renderer combines both to decide the marks, positions, and labels you see.",example:"A route can move to another position when the order changes. Its ridership count and route identity remain attached to it."},{title:"Follow the event",body:"A tap, click, or keyboard action can update chart state. Redraw the marks, legend, and readouts from that state so all parts of the view describe the same displayed records.",example:"When a rider selects a route, highlight the matching bar and show the count beside the chart."},{title:"Keep comparisons fair across updates",body:"A stable scale makes it easier to compare the same quantity before and after an interaction. If an interaction changes the scale or unit, update the axis and labels. Use a focusable control or inspectable value alongside pointer interactions.",example:"After sorting the bars, check that the largest value is unchanged and stays on the same length scale."}],quiz:[{prompt:"Sorting the bars by ridership changes which part of the chart?",options:["The count recorded for each route","The reporting period used to collect the data","Each bar\u2019s position in the displayed order"],correct:2,explanation:"Sorting moves the records in the display order. Each observed count continues to belong to the same route."},{prompt:"A filter changes which routes are visible. What should a count next to the chart report?",options:["The number of visible routes in the current selection","The number of bars before the last filter change","The total number of pointer clicks"],correct:0,explanation:"The readout should describe the same selection shown by the chart."},{prompt:"You want a route\u2019s bar length to be comparable before and after a sort. Which choice helps?",options:["Shuffle the colors on every interaction","Keep the same scale and unit","Set a different maximum for each bar"],correct:1,explanation:"A stable scale maps the same quantity to the same length across the two views."}]},{id:"web-linked-selection",title:"Link selection and detail",subtitle:"Use a shared record identity to connect a mark to its values.",kind:"scatter",slides:[{title:"Connect views by record ID",body:"Linked views use a stable record ID to refer to the same observation. Selecting a point can highlight that observation and show its values in a separate readout.",example:"Select a route in the scatterplot and inspect the rides and service frequency for that same route."},{title:"Distinguish selection from filtering",body:"A selection directs attention to one record or group. A filter limits which records are included in the view. A readout for the currently visible group should use the records that pass the filter.",example:"Highlighting one suburban route can leave urban routes visible for context. Filtering to suburban routes changes the population you are inspecting."},{title:"Preserve identity when the view moves",body:"Camera rotations and axis changes can make points overlap or change their screen positions. Link details by data IDs so the selected record stays the same as you inspect another view.",example:"A point can appear farther away in 3D after the camera rotates. Its recorded route values stay fixed."}],quiz:[{prompt:"Which field should link a point to its details after the view rotates?",options:["Its last screen pixel","Its stable record ID","Its distance from the camera"],correct:1,explanation:"A stable ID identifies the same record across different projections."},{prompt:"When you highlight one point and the others remain visible, what operation happened?",options:["The dataset was re-aggregated","All other records were removed by a filter","A record was selected"],correct:2,explanation:"Selection emphasizes a record and can preserve surrounding context."},{prompt:"A view is filtered to routes in one group. Which points describe that group\u2019s spread?",options:["The records that pass the current filter","Every record in the entire dataset","Only the closest point to the pointer"],correct:0,explanation:"The displayed spread should reflect the included records. Compare it with the full view if you want to assess what the filter changed."}]}]},{id:"unit-4",title:"Visual analytics and D3",subtitle:"Test whether a pattern survives a change in how you summarize the data.",reference:"CPS 5745 Day 18, Interactive data analytics. Day 23, D3 data binding. Days 24\u201325, Visual formatting and visual analytics.",lessons:[{id:"analytics-binning",title:"Stress-test a histogram",subtitle:"Vary the bins, check the counts, and record what persists.",kind:"histogram",slides:[{title:"Try another bin width",body:"A histogram summarizes a set of measurements using intervals. A small change in a bin boundary can move observations between neighboring bins. Compare multiple reasonable widths to see which patterns persist.",example:"Check whether the high-delay tail appears at several widths before describing it in a finding."},{title:"Make interval boundaries explicit",body:"For count histograms, each included observation should contribute to exactly one bin. A common rule includes the lower edge and excludes the upper edge, with the final bin including the ending boundary.",example:"If the bins are [0, 5) and [5, 10], a delay of exactly 5 belongs in the second bin. Add the bin counts and compare them with the displayed sample size."},{title:"Record the conditions behind the finding",body:"An exploratory claim is easier to reproduce when you report the dataset, units, filters, interval boundaries, and observed pattern. For comparisons, use the same bin edges and say whether height shows counts or shares.",example:"Report a wider right tail in one group only after comparing both groups on the same minute intervals."}],quiz:[{prompt:"Changing bin width made a small second peak disappear. What is a defensible first conclusion?",options:["The apparent peak is sensitive to the bin choice","The measurements changed","The missing peak proves that the remaining peak is wrong"],correct:0,explanation:"A finding that depends on one set of bin boundaries deserves a closer look. The underlying observations can be the same."},{prompt:"Bins follow [0, 5) and [5, 10]. Which bin receives a value of exactly 5?",options:["The first bin","Both bins","The second bin"],correct:2,explanation:"The first bin excludes 5 at its upper edge. The second includes 5 at its lower edge."},{prompt:"What should the sum of an unweighted count histogram\u2019s bin heights equal?",options:["The width of the data domain","The number of observations assigned to those bins","The largest observation"],correct:1,explanation:"Each assigned observation contributes one count. Check the displayed sample size to catch dropped or double-counted observations."}]},{id:"d3-data-join",title:"Keep marks matched to records",subtitle:"Follow D3\u2019s enter, update, and exit steps as the data changes.",kind:"bars",slides:[{title:"Bind each record by a stable key",body:"A D3 data join pairs incoming records with existing marks. A unique key such as route ID lets a mark retain its record when the new array is sorted differently.",example:"For bars representing routes, selection.data(rows, row => row.routeId) matches each bar by route ID."},{title:"Follow enter, update, and exit",body:"Incoming keys without marks enter. Keys present in both sets update. Old keys absent from the incoming data exit. A filter can trigger these steps even when the original dataset stays the same.",example:"If the visible routes change from A and B to B and C, A exits, B updates, and C enters."},{title:"Decide which attributes should change",body:"When a record stays in the chart, its visual attributes may still need recomputing. Update the mark\u2019s coordinates, size, and labels from the new values and scales. Keep the motion consistent with which record changed.",example:"If route B gains riders, its existing bar grows to the new length. A reordered route moves to its new position while retaining its identity."}],quiz:[{prompt:"The route IDs are unchanged, but their order changes. Which key keeps each route linked to its bar?",options:["Current row index","Route ID","Current catchment rank"],correct:1,explanation:"Route ID is stable across the reorder. The index or rank may identify a different route in the new array."},{prompt:"The chart changes from routes A and B to routes B and C. Which route enters?",options:["C","B","A"],correct:0,explanation:"C appears in the incoming set without an existing mark. B updates and A exits."},{prompt:"Route B stays in the chart and its ride count rises. What should happen to the mark?",options:["It should exit and remain absent","It should keep its previous length","It should update its length using the new count"],correct:2,explanation:"The route\u2019s key remains present, so the update changes the existing mark to represent its new value."}]}]}];var De=[{id:"unit-5",title:"Web requests and live data",subtitle:"Connect a chart to a query, then decide when and how to refresh it.",reference:"CPS 5745 Days 05\u201306, Three-tier websites and HTML forms. Day 09, Authentication and error handling. Days 10 and 17, Real-time visualization and Ajax. Day 26, Automation and APIs",lessons:[{id:"server-query",title:"From an input to a chart query",subtitle:"Follow a filter from the browser to a data service and back.",kind:"bars",slides:[{title:"Give each tier one job",body:"The browser collects a user\u2019s choices and draws the result. The application server validates those choices and decides which data the user can see. The database stores and queries the records.",example:"A route-group control specifies a group. The service returns approved counts for that group with a unit and reporting interval."},{title:"Validate and bind form values",body:"Check that choices match the expected types and ranges on the server. Bind accepted values as query parameters. If the interface lets users choose a grouping or sort field, map that choice to an allowed field name.",example:"A month filter accepts a calendar month. An unexpected value produces a validation message before the service runs the query."},{title:"Show the result state",body:"An empty result, a measured zero, and a failed request mean different things. Include the filter and reporting interval in the returned view. If a refresh fails, label any retained values with their previous timestamp.",example:"If a week has no matching records, show an empty result. A collected record with zero rides can appear as an observed zero."}],quiz:[{prompt:"Which tier should decide whether the current user can see a route\u2019s records?",options:["The application server","The chart axis labels","The selected bar color"],correct:0,explanation:"The application server checks the user\u2019s permissions before it returns records to the browser."},{prompt:"A month value comes from a form. How should the server include the value in a query?",options:["Append the raw input to the query string","Validate it and pass it as a bound parameter","Require the database to infer it from the chart title"],correct:1,explanation:"Validation enforces the input contract. A bound parameter passes the accepted value separately from the query structure."},{prompt:"A request failed and the chart still shows its last successful result. What should appear beside those values?",options:["The latest requested interval as if it succeeded","An observed zero for every route","A failed-refresh message and the time of the retained data"],correct:2,explanation:"The message explains the request outcome. The prior timestamp tells viewers when the displayed values were last obtained."}]},{id:"live-refresh",title:"Refresh data over time",subtitle:"Distinguish a new observation from the arrival of its report.",kind:"line",slides:[{title:"Choose a refresh schedule",body:"A browser can pull snapshots on a timer or receive pushed updates. A scheduled server job can build a shared snapshot at a known interval. Match the update frequency to how often measurements arrive and how soon viewers need them.",example:"A daily planning chart can use a scheduled daily summary. A short-window service monitor may need a more frequent source."},{title:"Order by observation time",body:"A record can arrive after newer records were already displayed. Use its observation timestamp to place it on the chart. Report freshness separately so a delayed arrival does not look like a newly measured event.",example:"A report received at 10:14 for a 10:00 observation belongs at 10:00 on the time axis."},{title:"Handle overlaps and missing updates",body:"A slow request can finish after a newer request. Track data versions or request IDs before updating the visible state. Preserve meaningful gaps when a time interval has no observation.",example:"If snapshot 4 finishes after snapshot 5, a version check keeps the view on snapshot 5. A missed interval can remain a gap."}],quiz:[{prompt:"A measurement observed at 10:00 reaches the service at 10:14. Where does it belong on an observation-time chart?",options:["At 10:14","At the latest available mark","At 10:00"],correct:2,explanation:"The horizontal position encodes when the event was measured. The arrival time is useful freshness metadata."},{prompt:"Snapshot 4 finishes after the chart already rendered snapshot 5. Which action preserves the latest data?",options:["Keep snapshot 5 by checking response versions","Always render the last response to arrive","Average the two snapshots without checking their intervals"],correct:0,explanation:"Checking the version prevents a late older response from replacing newer data."},{prompt:"A refresh clock ticks, but the source has no new measurement. What can the chart conclude?",options:["The last value was measured again","The interface checked for an update","The measured value fell to zero"],correct:1,explanation:"A timer records an update attempt. A new point requires an observation from the source."}]}]},{id:"unit-6",title:"Python for visual exploration",subtitle:"Prepare tabular data, check the plotted sample, and test a visual interpretation.",reference:"CPS 5745 Day 25, Visual analytics and data mining. Day 27, Python, pandas, matplotlib, and GeoPandas. Day 28, Visualization using Python and MySQL",lessons:[{id:"pandas-prep",title:"Prepare a table for plotting",subtitle:"Check types and missing values before drawing the chart.",kind:"bars",slides:[{title:"Check the table\u2019s grain and types",body:"A pandas DataFrame organizes data in rows and columns. Decide what one row means. Inspect column types and parse units and dates before grouping, sorting, or labeling a chart.",example:"A weekly ridership table can use one row per route and week. Convert the count column to a nullable number before calculating a mean."},{title:"Track how missing values affect a statistic",body:"A recorded zero contributes to a total and a mean. An unknown count can be represented as missing. Compare the number of recorded values with the number of rows so the plotted summary has a clear denominator.",example:"Counts 8, 0, and missing give 3 rows, 2 recorded measurements, and a mean of 4 rides per recorded row."},{title:"Plot the prepared table",body:"After cleaning and grouping, send the intended columns to matplotlib. Use the same units on the axis and in the chart caption. Keep the table used to produce the plot so viewers can check the marks.",example:"Plot route name on the category axis and valid ride-count records as bar height. Label an axis in records if the analysis counts observations."}],quiz:[{prompt:'A ridership column contains the strings "16" and "4". What should happen before calculating their numerical mean?',options:["Sort the columns by name","Parse and validate the column as numeric","Choose a bar color for each string"],correct:1,explanation:"Numeric conversion prepares the values for numerical aggregation and exposes entries that fail validation."},{prompt:"Values are 8, 0, and missing. What is their mean using recorded values?",options:["About 2.67","8","4"],correct:2,explanation:"The recorded zero is part of the sample. The sum is 8 and the number of recorded values is 2."},{prompt:"Bar height gives how many route-week rows contain a valid measurement. Which unit describes the vertical axis?",options:["Records","Rides","Weeks per rider"],correct:0,explanation:"This chart counts records. A chart of total rides would sum the measurement values and use a different unit."}]},{id:"visual-mining",title:"Investigate a pattern",subtitle:"Use an interactive plot to refine a question about the data.",kind:"scatter",slides:[{title:"Start with a comparison question",body:"Visual exploration can reveal groups, trends, and unusual observations. Record the fields, sample, and filters so another person can reproduce what you saw. Shape a follow-up test around a specific observation.",example:"Select a point with high ridership and examine its service frequency, ride count, and travel time in the inspector."},{title:"Inspect groups in the same units",body:"Separate plausible groups and compare their patterns using consistent axes. Combinations of groups can create associations that look weaker or different within a group.",example:"Compare a selected route group with the combined view. Keep the same frequency and ridership scales when judging the change."},{title:"Verify before explaining",body:"An apparent cluster can depend on a filter, scale, or projection. Rotate the 3D plot, compare the 2D view, and inspect the original records. A pattern can motivate a check of an explanation.",example:"Rotate to reveal points that overlap in one view. Compare their recorded values before describing them as similar."}],quiz:[{prompt:"After rotation, two points that appeared to overlap separate. What does this tell you?",options:["The underlying ride counts changed","The screen projection hid part of their separation","The dataset gained a record"],correct:1,explanation:"The same 3D data points project differently as the camera moves. Inspect the values to evaluate their differences."},{prompt:"What should you record so someone else can reproduce an exploratory chart result?",options:["Only the chart background color","Only the first point selected","The dataset, fields, units, filters, and observed pattern"],correct:2,explanation:"These details specify the input, the visual encoding, and the conditions behind the observation."},{prompt:"A positive relationship is strong in the combined view but weaker within each route group. What should you check?",options:["How the group populations differ and how the combined pattern changes","Whether rotating the camera changes the underlying observations","Whether using larger dots makes the relationship causal"],correct:0,explanation:"Group composition can influence an aggregate pattern. Compare the groups and identify other variables before proposing an explanation."}]}]}];var he=[Se,...Ie,...De];var z=e=>document.getElementById(e),Re=e=>`Day ${String(e.day).padStart(2,"0")}`,N=e=>e.split("/").at(-1).toLowerCase();function Le(e){return`#lectures/day-${String(e).padStart(2,"0")}`}functi